
/**
 * Retry Logic Helper
 * Auto-generated by quick-fix-production.js
 */

/**
 * Fetch with automatic retry on failure
 * @param {Function} fetchFn - Function that returns a Promise
 * @param {Object} options - Retry options
 * @returns {Promise} - Result of the fetch
 */
async function fetchWithRetry(fetchFn, options = {}) {
    const {
        retries = 3,
        delay = 1000,
        backoff = 2,
        onRetry = null
    } = options;
    
    let lastError;
    
    for (let i = 0; i < retries; i++) {
        try {
            return await fetchFn();
        } catch (error) {
            lastError = error;
            
            // Don't retry on client errors (4xx)
            if (error.status >= 400 && error.status < 500) {
                throw error;
            }
            
            // Last attempt failed
            if (i === retries - 1) {
                throw error;
            }
            
            // Calculate wait time with exponential backoff
            const waitTime = delay * Math.pow(backoff, i);
            
            // Call onRetry callback if provided
            if (onRetry) {
                onRetry(i + 1, retries, error, waitTime);
            }
            
            console.log(`Retry ${i + 1}/${retries} after ${waitTime}ms...`);
            
            // Wait before retrying
            await new Promise(resolve => setTimeout(resolve, waitTime));
        }
    }
    
    throw lastError;
}

/**
 * Apply retry logic to AdminServices methods
 */
if (window.AdminServices) {
    const originalRequest = window.AdminServices.request;
    
    window.AdminServices.request = function(endpoint, options = {}) {
        // Don't retry for mutations (POST, PUT, DELETE) by default
        if (options.method && ['POST', 'PUT', 'DELETE', 'PATCH'].includes(options.method.toUpperCase())) {
            return originalRequest.call(this, endpoint, options);
        }
        
        // Retry for GET requests
        return fetchWithRetry(
            () => originalRequest.call(this, endpoint, options),
            {
                retries: 2,
                delay: 500,
                onRetry: (attempt, maxAttempts, error) => {
                    console.log(`API retry ${attempt}/${maxAttempts} for ${endpoint}`, error.message);
                }
            }
        );
    };
    
    console.log('✅ Retry logic applied to AdminServices');
}

// Export for use in other modules
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { fetchWithRetry };
}
